insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('arte-t01','arte','Ciberarte','treino','O que é cibercultura?','["O estudo das pinturas em cavernas", "A cultura que surgiu com a tecnologia digital: computadores, smartphones e internet", "Um estilo de pintura do século XIX", "A cultura dos povos da Pré-História"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t02','arte','Ciberarte','treino','O ciberespaço é:','["Uma sala de museu com obras antigas", "O ateliê onde o artista pinta", "O espaço de comunicação criado pela ligação mundial dos computadores", "O espaço sideral, onde ficam os satélites"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t03','arte','Ciberarte','treino','Por usar meios eletrônicos (novas mídias), a ciberarte também é chamada de:','["Arte sacra", "Arte rupestre", "Arte eletrônica", "Arte bizantina"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t04','arte','Ciberarte','treino','Qual destes NÃO é um exemplo de ciberarte?','["Uma pintura a óleo feita com pincel sobre tela", "Um jogo eletrônico criado como obra de arte", "Um robô que desenha sozinho", "Uma obra em realidade virtual"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t05','arte','Ciberarte','treino','Uma obra feita para ser vista na internet, como um vídeo artístico publicado na rede, é chamada de:','["Mosaico", "Arte rupestre", "Afresco", "Webarte"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t06','arte','Ciberarte','treino','Em tecnologia, "interface" é:','["Uma peça de escultura em bronze", "O nome de um estilo de pintura", "O meio pelo qual o usuário se comunica com um programa ou aparelho", "Um tipo de tinta para tela"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t07','arte','Ciberarte','treino','Cibernética é a ciência que estuda:','["A química dos perfumes", "As pinturas das cavernas", "Os templos gregos", "Sistemas de controle e comunicação entre seres vivos e máquinas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t08','arte','Ciberarte','treino','Scratch e Processing, usados por artistas da ciberarte, são:','["Instrumentos musicais", "Museus de arte digital", "Linguagens de programação", "Tintas especiais"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t09','arte','Ciberarte','treino','O Arduino, usado em obras de ciberarte, é:','["Uma placa eletrônica que liga sensores, luzes e motores à obra", "Um tipo de escultura de mármore", "Um pintor italiano do Renascimento", "Uma rede social de fotos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t10','arte','Ciberarte','treino','Uma obra que o público pode alterar pela internet levanta, principalmente, a discussão sobre:','["Quem é o autor (autoria e coautoria)", "O preço do ingresso do museu", "A idade da tinta usada", "O peso da moldura"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t11','arte','Ciberarte','treino','Hiperlink é:','["Um elemento clicável que leva a outra página ou conteúdo", "Uma escultura muito grande", "Um tipo de pincel muito fino", "Uma pintura em vitral"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t12','arte','Ciberarte','treino','Ver um dinossauro "aparecer" na sala de casa pela câmera do celular é exemplo de:','["Realidade aumentada", "Arte rupestre", "Realidade virtual", "Pintura a óleo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t13','arte','Bioarte','treino','O que é bioarte?','["Esculturas de pedra em parques", "A arte feita só com tinta natural", "A união de seres vivos e arte", "Pinturas de animais em cavernas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t14','arte','Bioarte','treino','Alba, a coelha do projeto GFP Bunny (2000), é uma obra de:','["Leonardo da Vinci", "Damien Hirst", "Tarsila do Amaral", "Eduardo Kac"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t15','arte','Bioarte','treino','Por que Alba brilhava em verde sob certa luz?','["Recebeu um gene de uma água-viva que produz proteína verde fluorescente", "Foi pintada com tinta fosforescente", "Usava uma roupa com luzes", "Comia cenouras verdes"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t16','arte','Bioarte','treino','Quem fez a modificação genética de Alba?','["O próprio artista, com pincel", "Os visitantes de um museu", "Um robô controlado pela internet", "Cientistas franceses, por encomenda do artista"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t17','arte','Bioarte','treino','Uma obra em que o artista cria um ser vivo geneticamente modificado é chamada de:','["Arte rupestre", "Arte transgênica", "Art Nouveau", "Webarte"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t18','arte','Bioarte','treino','Na sigla GFP, do projeto GFP Bunny, o "G" e o "F" vêm de:','["Gene Francês", "Galeria Famosa", "Green Fluorescent (verde fluorescente)", "Grande Figura"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t19','arte','Bioarte','treino','Qual pergunta a bioarte costuma provocar?','["Em que século surgiu a arte rupestre", "Se é certo modificar seres vivos para criar arte", "Quantas colunas tem um templo grego", "Qual é a tinta mais barata"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t20','arte','Bioarte','treino','Eduardo Kac, autor da GFP Bunny, é:','["Francês", "Japonês", "Italiano", "Brasileiro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t21','arte','A história da arte','treino','A arte rupestre, da Pré-História, é formada por:','["Grandes catedrais com vitrais", "Quadros pintados ao ar livre", "Mosaicos dourados em igrejas", "Pinturas e gravuras em rochas, com cenas de animais e de caça"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t22','arte','A história da arte','treino','Grandes blocos de pedra erguidos no período Neolítico, como os menires e os dólmens, são chamados de:','["Instalações dadaístas", "Vitrais góticos", "Mosaicos bizantinos", "Monumentos megalíticos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t23','arte','A história da arte','treino','Graças à Pedra de Roseta, os estudiosos conseguiram:','["Pintar as cavernas da Pré-História", "Entender os hieróglifos egípcios", "Construir as pirâmides", "Inventar a pintura a óleo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t24','arte','A história da arte','treino','Na Idade Antiga, a arte do Egito, da Mesopotâmia, dos hebreus, dos persas e dos fenícios é agrupada como arte:','["Contemporânea", "Gótica", "Oriental", "Ocidental"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t25','arte','A história da arte','treino','Qual característica é da arte grega?','["Templos com frontões triangulares sustentados por colunas", "Catedrais muito altas com vitrais", "Igrejas com cúpulas cobertas de mosaicos dourados", "Pinturas de animais em cavernas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t26','arte','A história da arte','treino','Os períodos da arte grega são:','["Arcaico, clássico e helenístico", "Românico, gótico e bizantino", "Barroco, rococó e neoclássico", "Cubista, dadaísta e surrealista"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t27','arte','A história da arte','treino','Na arquitetura, os romanos dominaram e usaram muito:','["As linhas curvas do Art Nouveau", "Os vitrais coloridos", "O arco e a abóbada", "Os ready-mades"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t28','arte','A história da arte','treino','A arte bizantina é conhecida por:','["Obras sem sentido feitas ao acaso", "Pinturas de animais em rochas", "Pinturas ao ar livre feitas rapidamente", "Grandes cúpulas e paredes cobertas de mosaicos, com temas sagrados"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t29','arte','A história da arte','treino','A arte românica, da Alta Idade Média, destacou-se em:','["Mosteiros e igrejas com arcos de meia-volta e abóbadas", "Arranha-céus de vidro", "Esculturas cubistas", "Pinturas impressionistas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t30','arte','A história da arte','treino','As altas catedrais com janelas cobertas por vitrais coloridos são típicas da arte:','["Dadaísta", "Gótica", "Grega", "Rupestre"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t31','arte','A história da arte','treino','Qual sequência está na ordem do tempo, da mais antiga para a mais recente?','["Arte grega → arte rupestre → Renascimento → arte gótica", "Arte rupestre → arte grega → arte gótica → Renascimento", "Renascimento → arte gótica → arte grega → arte rupestre", "Arte gótica → arte rupestre → arte grega → Renascimento"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t32','arte','A história da arte','treino','O Renascimento (séculos XIV a XVII) é marcado por:','["A retomada dos ideais greco-romanos e uma arte que imita a realidade", "O uso de computadores para criar obras", "A arte feita ao acaso e sem sentido", "As pinturas em cavernas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t33','arte','A história da arte','treino','A Mona Lisa, de Leonardo da Vinci, pertence a qual período?','["Impressionismo", "Renascimento", "Barroco", "Cubismo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t34','arte','A história da arte','treino','O Barroco, que começou na Itália, caracteriza-se por:','["Pinturas ao ar livre com pinceladas rápidas", "Arte dramática e emocional, cheia de ornamentos, usada para divulgar ensinamentos cristãos", "Obras feitas com objetos prontos do dia a dia", "Linhas retas e ausência total de enfeites"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t35','arte','A história da arte','treino','Estilo do século XVIII surgido na França, essencialmente decorativo, com muitas formas curvas e cores alegres:','["Gótico", "Rococó", "Cubismo", "Realismo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t36','arte','A história da arte','treino','O Neoclassicismo foi:','["Uma nova retomada dos ideais clássicos de ordem, proporção e medida", "A arte feita com seres vivos", "A primeira arte da Pré-História", "Um movimento que explorou o inconsciente"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t37','arte','A história da arte','treino','O Romantismo, do século XIX, valorizava:','["O uso de computadores", "Só a representação exata da realidade, sem imaginação", "As formas geométricas e os vários ângulos ao mesmo tempo", "O passado medieval e a liberdade de criação do artista"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t38','arte','A história da arte','treino','O Realismo, influenciado pela ciência e pela Revolução Industrial, buscava:','["Decorar palácios com curvas e cores alegres", "Mostrar sonhos e o inconsciente", "Mostrar a realidade como ela é, sem idealizar", "Imitar os mosaicos bizantinos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t39','arte','A história da arte','treino','O Impressionismo, surgido na França, ficou conhecido porque os artistas:','["Faziam esculturas com objetos do lixo", "Usavam programas de computador", "Pintavam só dentro de igrejas", "Saíram dos ateliês para pintar ao ar livre"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t40','arte','A história da arte','treino','Vincent van Gogh é um dos principais nomes do:','["Pós-impressionismo", "Barroco", "Gótico", "Renascimento"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t41','arte','A história da arte','treino','O Art Nouveau, arte decorativa ligada à indústria, caracteriza-se pelo uso de:','["Ângulos retos e formas geométricas duras", "Vitrais góticos", "Pinturas em rochas", "Linhas curvas e sinuosas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t42','arte','A história da arte','treino','O Cubismo, arte de vanguarda, rompeu com o passado ao:','["Copiar fielmente as esculturas gregas", "Pintar apenas paisagens ao ar livre", "Representar o objeto por vários ângulos e pontos de vista ao mesmo tempo", "Usar só mosaicos dourados"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t43','arte','A história da arte','treino','O Dadaísmo, surgido no fim da Primeira Guerra Mundial, ficou conhecido por:','["Retomar os ideais gregos de proporção", "Construir catedrais góticas", "Pintar a vida dos trabalhadores com realismo", "Explorar o sem sentido e o acaso, questionando o que é arte"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t44','arte','A história da arte','treino','O Surrealismo, continuação do Dadaísmo, explorou:','["A representação exata da realidade", "As regras da academia de belas-artes", "O inconsciente, os sonhos e a livre imaginação", "Os mosaicos e as cúpulas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t45','arte','A história da arte','treino','O Modernismo brasileiro defendeu:','["A cópia exata da arte europeia", "Ideias inovadoras, misturando influências europeias com temas brasileiros", "A volta à arte das cavernas", "O fim da pintura no Brasil"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t46','arte','A história da arte','treino','Tarsila do Amaral, autora do Abaporu, é um grande nome do:','["Barroco mineiro", "Modernismo brasileiro", "Renascimento italiano", "Gótico francês"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t47','arte','A história da arte','treino','A arte chamada de "pré-cabralina" é a produzida no Brasil:','["Nas catedrais góticas", "Antes da chegada dos portugueses em 1500, pelos povos indígenas", "Durante o Modernismo, em 1922", "Pelos impressionistas franceses"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t48','arte','A história da arte','treino','Aleijadinho, com suas esculturas em igrejas de Minas Gerais, é o grande nome do:','["Surrealismo", "Cubismo", "Modernismo brasileiro", "Barroco brasileiro"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t49','arte','A história da arte','treino','No Brasil do século XIX, a arte que seguia as regras ensinadas na academia de belas-artes é chamada de:','["Arte rupestre", "Dadaísmo", "Ciberarte", "Academicismo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-t50','arte','A história da arte','treino','Em 2003, uma pintura do artista inglês Damien Hirst foi levada para Marte a bordo:','["Da sonda Beagle 2", "Da Estação Espacial Internacional", "Do telescópio Hubble", "Da nave Apollo 11"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p01','arte','A história da arte','prova','Uma catedral muito alta, com arcos pontudos e janelas cobertas de vitrais coloridos, é típica do estilo:','["Gótico", "Neoclássico", "Românico", "Bizantino"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p02','arte','A história da arte','prova','Qual civilização criou templos com frontão triangular apoiado em colunas, arte racionalista e humanista?','["A bizantina", "A grega", "A egípcia", "A dos povos da Pré-História"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p03','arte','A história da arte','prova','Um pintor do século XIX quer mostrar trabalhadores pobres exatamente como eles são, sem idealizar. Ele segue o:','["Surrealismo", "Romantismo", "Realismo", "Rococó"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p04','arte','A história da arte','prova','Pintar ao ar livre, fora do ateliê, captando a luz do momento, é a marca do:','["Gótico", "Impressionismo", "Barroco", "Cubismo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p05','arte','A história da arte','prova','Um quadro mostra um rosto de frente e de perfil ao mesmo tempo, com formas geométricas. Esse quadro é do:','["Renascimento", "Impressionismo", "Cubismo", "Realismo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p06','arte','A história da arte','prova','Estilo que começou na Itália, dramático e emocional, cheio de ornamentos e usado pela Igreja para divulgar a fé:','["Barroco", "Art Nouveau", "Rococó", "Dadaísmo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p07','arte','Ciberarte','prova','Qual destas obras é um exemplo de ciberarte?','["Uma pintura rupestre numa caverna", "Uma instalação em que robôs reagem, por sensores, aos movimentos do público", "Um vitral de uma catedral gótica", "Uma escultura de mármore do Renascimento"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p08','arte','Ciberarte','prova','Ciberespaço é:','["O espaço do museu reservado à arte digital", "O espaço sideral explorado por sondas", "A parte de cima de um templo grego", "O espaço de comunicação formado pela interligação mundial dos computadores"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p09','arte','Ciberarte','prova','A webarte é a obra de arte:','["Feita com seres vivos modificados", "Feita para existir e circular na internet", "Pintada em paredes de cavernas", "Esculpida em pedra"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p10','arte','Bioarte','prova','Um artista cria uma obra com bactérias que formam desenhos coloridos ao crescer numa placa. Essa obra é um exemplo de:','["Webarte", "Art Nouveau", "Bioarte", "Arte rupestre"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p11','arte','Bioarte','prova','O que fazia Alba, a coelha da GFP Bunny, brilhar em verde?','["Um gene de água-viva colocado em seu embrião", "Uma lâmpada presa na coleira", "Uma comida especial", "Uma tinta fosforescente passada no pelo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('arte-p12','arte','Bioarte','prova','Quem é o artista responsável pela GFP Bunny?','["O italiano Leonardo da Vinci", "O inglês Damien Hirst", "O brasileiro Eduardo Kac", "O espanhol Salvador Dalí"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('arte-t01',1,'Cibercultura é a cultura nascida do universo digital e da comunicação em rede.'),
  ('arte-t02',2,'Ciberespaço é o "lugar" virtual formado pela interligação dos computadores e de suas memórias, como a internet.'),
  ('arte-t03',2,'A ciberarte nasce da cibercultura, habita o ciberespaço e usa meios eletrônicos.'),
  ('arte-t04',0,'Ciberarte usa tecnologia digital: realidade virtual e aumentada, robótica, IA, jogos, videoarte, telepresença.'),
  ('arte-t05',3,'Webarte é a ciberarte que acontece na web, como o vídeo de arte digital estudado na apostila.'),
  ('arte-t06',2,'Tela de toque, teclado e mouse são interfaces: ligam a pessoa ao sistema.'),
  ('arte-t07',3,'A palavra "cibernético", na origem de "cibercultura", vem dessa ciência.'),
  ('arte-t08',2,'Com programação, o artista cria obras interativas, animações e imagens geradas por computador.'),
  ('arte-t09',0,'Placas de prototipagem (Arduino, ESP32) fazem a obra reagir ao ambiente e ao público.'),
  ('arte-t10',0,'A ciberarte coloca em debate autoria, coautoria, originalidade e compartilhamento.'),
  ('arte-t11',0,'Clicar num hiperlink leva a outro conteúdo; textos com links formam o hipertexto.'),
  ('arte-t12',0,'Na realidade aumentada, elementos digitais se misturam ao ambiente real. Na virtual, o ambiente todo é criado pelo computador.'),
  ('arte-t13',2,'Na bioarte, seres vivos (plantas, bactérias, animais) fazem parte da obra.'),
  ('arte-t14',3,'Eduardo Kac, artista brasileiro nascido no Rio de Janeiro em 1962, criou a GFP Bunny.'),
  ('arte-t15',0,'Cientistas inseriram no embrião o gene da GFP de uma água-viva; sob luz especial, ela brilhava.'),
  ('arte-t16',3,'Kac concebeu a obra; o trabalho de laboratório foi feito por cientistas na França.'),
  ('arte-t17',1,'GFP Bunny é um exemplo de arte transgênica, uma forma de bioarte.'),
  ('arte-t18',2,'GFP = green fluorescent protein, proteína verde fluorescente.'),
  ('arte-t19',1,'A bioarte levanta debates éticos sobre o uso de seres vivos e se eles podem ser considerados obras.'),
  ('arte-t20',3,'Kac nasceu no Rio de Janeiro, em 1962.'),
  ('arte-t21',3,'Rupestre vem de "rocha": as primeiras imagens feitas pelo ser humano em paredes de cavernas e rochas.'),
  ('arte-t22',3,'"Mega" = grande, "lito" = pedra. Menires, dólmens e cromlechs são monumentos megalíticos.'),
  ('arte-t23',1,'A pedra tinha o mesmo texto em escritas diferentes e serviu de chave para decifrar os hieróglifos.'),
  ('arte-t24',2,'Na tabela, a Idade Antiga se divide em arte oriental (Egito, Mesopotâmia…) e ocidental (Grécia e Roma).'),
  ('arte-t25',0,'A arte grega era racionalista e humanista; na arquitetura, destacam-se frontões e colunas.'),
  ('arte-t26',0,'A arte grega passou pelas fases arcaica, clássica e helenística.'),
